// GENERATED by port-tests.py from ../xb-chat/test: the Node tests, run against the Rust server.
// End-to-end: real servers on random ports, real clients over TCP and HTTP.

import assert from 'node:assert/strict';
import { createHash, randomBytes } from 'node:crypto';
import { promises as fs } from 'node:fs';
import net from 'node:net';
import os from 'node:os';
import path from 'node:path';
import { after, before, describe, test } from 'node:test';
import { startRust } from './rust.js';
import { Client } from '../../xb-chat/clients/node/client.js';
import { MemoryKeyStore } from '../../xb-chat/clients/node/signal-node.js';
import { frame } from '../../xb-chat/protocol/framing.js';
import { generateKeyPair } from '../../xb-chat/protocol/noise.js';
import { HEADER } from '../../xb-chat/protocol/tokens.js';
import { Transport } from '../../xb-chat/protocol/transport.js';

let dir;
let chat;
let media;
const serverKey = generateKeyPair(); // kept across restarts, like data/server_key
const clients = [];
// Each user's device storage (end-to-end keys and sessions), kept across
// reconnects like a phone's.
const keyStores = new Map();
const keysOf = (user) => {
  if (!keyStores.has(user)) keyStores.set(user, new MemoryKeyStore());
  return keyStores.get(user);
};

async function startServers() {
  chat = await startRust({ dir, staticKeyPair: serverKey });
  media = chat.media;
  media.sweep = () => chat.store.expireMedia();
}

async function stopServers() {
  for (const c of clients.splice(0)) c.close();
  await chat.close();
}

async function connect(user, { register = false, ...opts } = {}) {
  const c = new Client({ port: chat.port, keyStore: keysOf(user), ...opts });
  c.on('error', () => {});
  clients.push(c);
  await c.connect();
  await (register ? c.register(user, 'password1') : c.login(user, 'password1'));
  return c;
}

// Resolves with the next `event` from `emitter` that matches `filter`.
function next(emitter, event, filter = () => true, ms = 3000) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error(`timed out waiting for ${event}`)), ms);
    const on = (v) => {
      if (!filter(v)) return;
      clearTimeout(timer);
      emitter.off(event, on);
      resolve(v);
    };
    emitter.on(event, on);
  });
}

const tick = (ms = 50) => new Promise((r) => setTimeout(r, ms));

before(async () => {
  dir = await fs.mkdtemp(path.join(os.tmpdir(), 'xb-test-'));
  await startServers();
  for (const u of ['alice', 'bob', 'carol', 'dave']) (await connect(u, { register: true })).close();
  await tick();
});

after(async () => {
  await stopServers();
  await fs.rm(dir, { recursive: true, force: true });
});

describe('auth', () => {
  test('rejects a wrong password and a taken username', async () => {
    const c = new Client({ port: chat.port });
    clients.push(c);
    await c.connect();
    await assert.rejects(c.login('alice', 'nope-nope'), { code: 'not-authorized' });
    await assert.rejects(c.register('alice', 'password1'), { code: 'user-exists' });
    await assert.rejects(c.register('A!', 'password1'), { code: 'invalid-user' });
  });

  test('closes connections with a bad header or a bogus handshake', async () => {
    for (const bytes of [
      Buffer.from('GET / HTTP/1.1\r\n\r\n'),
      Buffer.concat([Buffer.from([0x58, 0x42, 1, 1]), frame(Buffer.alloc(32))]), // old version
      Buffer.concat([HEADER, frame(Buffer.alloc(5))]), // too short for an ephemeral key
      Buffer.concat([HEADER, frame(Buffer.alloc(4000))]), // oversized handshake message
    ]) {
      const sock = net.connect(chat.port, '127.0.0.1');
      await new Promise((r) => sock.once('connect', r));
      sock.resume(); // drain so we see the server close
      sock.write(bytes);
      await new Promise((r) => sock.once('close', r));
    }
  });

  test('closes an encrypted connection that skips auth', async () => {
    const sock = net.connect(chat.port, '127.0.0.1');
    const t = new Transport(sock, { initiator: true, staticKeyPair: generateKeyPair() });
    t.on('error', () => {});
    const nodes = [];
    t.on('node', (n) => nodes.push(n));
    await new Promise((r) => {
      t.once('ready', r);
      sock.once('connect', () => t.start());
    });
    t.send({ tag: 'message', attrs: { id: '1', to: 'bob@s.xb' }, content: 'x' });
    await new Promise((r) => t.once('close', r));
    assert.deepEqual(nodes.map((n) => [n.tag, n.attrs.code]), [['stream:error', 'not-authorized']]);
  });

  test('a pinned client refuses a server with a different key', async () => {
    const good = new Client({ port: chat.port, serverPublicKey: serverKey.public.toString('base64') });
    clients.push(good);
    assert.ok((await good.connect()).equals(serverKey.public));
    const bad = new Client({ port: chat.port, serverPublicKey: generateKeyPair().public });
    clients.push(bad);
    await assert.rejects(bad.connect(), /pinned/);
  });

  test('a second login kicks the first connection', async () => {
    const first = await connect('dave');
    const kicked = next(first, 'stream_end');
    const second = await connect('dave');
    assert.equal(await kicked, 'conflict');
    second.close();
  });
});

describe('one-to-one messages', () => {
  test('ack, delivered and read receipts', async () => {
    const alice = await connect('alice');
    const bob = await connect('bob');

    const got = next(bob, 'message');
    const delivered = next(alice, 'receipt', (r) => r.type === 'delivered');
    const ack = await alice.sendMessage('bob', 'hello bob');
    assert.ok(ack.t > 0);

    const msg = await got;
    assert.equal(msg.text, 'hello bob');
    assert.equal(msg.from, 'alice@s.xb');
    assert.equal(msg.id, ack.id);
    assert.equal((await delivered).id, ack.id);

    const read = next(alice, 'receipt', (r) => r.type === 'read');
    bob.markRead(msg);
    const r = await read;
    assert.equal(r.from, 'bob@s.xb');

    await tick();
    assert.equal(await chat.store.pendingCount('bob'), 0, 'message left the queue after the receipt');
    assert.equal(await chat.store.pendingCount('alice'), 0, 'receipts left the queue after the ack');
    alice.close();
    bob.close();
  });

  test('unknown recipient is refused', async () => {
    const alice = await connect('alice');
    await assert.rejects(alice.sendMessage('nobody', 'hi'), { code: 'item-not-found' });
    alice.close();
  });

  test('a large message goes through with little overhead', async () => {
    const alice = await connect('alice');
    const bob = await connect('bob');
    const text = 'stock count: shelf 4 ok, shelf 5 ok, shelf 6 ok. '.repeat(400); // ~20 KB
    const got = next(bob, 'message');
    const before = alice.bytesOut;
    await alice.sendMessage('bob', text);
    assert.equal((await got).text, text);
    // End-to-end ciphertext does not compress, but costs only ~100 B more than the text.
    const sent = alice.bytesOut - before;
    assert.ok(sent < text.length + 400, `sent ${sent} B for ${text.length} B of text`);
    alice.close();
    bob.close();
  });

  test('typing indicator reaches an online peer', async () => {
    const alice = await connect('alice');
    const bob = await connect('bob');
    const typing = next(bob, 'chatstate');
    alice.typing('bob');
    assert.deepEqual(await typing, { from: 'alice@s.xb', participant: undefined, state: 'composing' });
    alice.close();
    bob.close();
  });
});

describe('offline delivery', () => {
  test('queued while offline, delivered on login, receipt reaches offline sender', async () => {
    const alice = await connect('alice');
    await alice.sendMessage('carol', 'first');
    await alice.sendMessage('carol', 'second');
    alice.close();
    await tick();
    assert.equal(await chat.store.pendingCount('carol'), 2);

    const carol = new Client({ port: chat.port, keyStore: keysOf('carol') });
    clients.push(carol);
    const texts = [];
    carol.on('message', (m) => texts.push(m.text));
    await carol.connect();
    const { offline } = await carol.login('carol', 'password1');
    assert.equal(offline, 2);
    await tick();
    assert.deepEqual(texts, ['first', 'second'], 'in order');
    assert.equal(await chat.store.pendingCount('carol'), 0);
    assert.equal(await chat.store.pendingCount('alice'), 2, 'two delivered receipts wait for alice');
    carol.close();

    const alice2 = new Client({ port: chat.port, keyStore: keysOf('alice') });
    clients.push(alice2);
    const receipts = [];
    alice2.on('receipt', (r) => receipts.push(r.type));
    await alice2.connect();
    await alice2.login('alice', 'password1');
    await tick();
    assert.deepEqual(receipts, ['delivered', 'delivered']);
    assert.equal(await chat.store.pendingCount('alice'), 0);
    alice2.close();
  });

  test('redelivered if the connection drops before the receipt', async () => {
    const alice = await connect('alice');
    const bob = await connect('bob', { autoDelivered: false });
    const got = next(bob, 'message');
    await alice.sendMessage('bob', 'are you there?');
    await got;
    bob.close(); // no receipt sent
    await tick();
    assert.equal(await chat.store.pendingCount('bob'), 1);

    const bob2 = new Client({ port: chat.port, keyStore: keysOf('bob') });
    clients.push(bob2);
    const again = next(bob2, 'message');
    await bob2.connect();
    await bob2.login('bob', 'password1');
    assert.equal((await again).text, 'are you there?');
    await tick();
    assert.equal(await chat.store.pendingCount('bob'), 0);
    alice.close();
    bob2.close();
  });

  test('retrying the same message id does not duplicate it', async () => {
    const alice = await connect('alice');
    await alice.sendMessage('carol', 'once', { id: 'FIXEDID1' });
    await alice.sendMessage('carol', 'once', { id: 'FIXEDID1' });
    assert.equal(await chat.store.pendingCount('carol'), 1);
    alice.close();
    const carol = await connect('carol');
    await tick();
    carol.close();
  });

  test('the queue survives a server restart', async () => {
    const alice = await connect('alice');
    await alice.sendMessage('carol', 'before restart');
    alice.close();
    await tick();
    await stopServers();
    await startServers();

    const carol = new Client({ port: chat.port, keyStore: keysOf('carol') });
    clients.push(carol);
    const got = next(carol, 'message');
    await carol.connect();
    await carol.login('carol', 'password1');
    assert.equal((await got).text, 'before restart');
    carol.close();
  });
});

describe('groups', () => {
  test('create, fan out, per-member receipts, membership rules', async () => {
    const alice = await connect('alice');
    const bob = await connect('bob');
    const carol = await connect('carol');
    const dave = await connect('dave');

    const g = await alice.createGroup('Store team', ['bob', 'carol']);
    assert.equal(g.participants.length, 3);
    assert.equal(g.participants.find((p) => p.jid === 'alice@s.xb').role, 'admin');

    const atBob = next(bob, 'message');
    const atCarol = next(carol, 'message');
    const receipts = [];
    alice.on('receipt', (r) => receipts.push(`${r.participant}:${r.type}`));
    const ack = await alice.sendGroupMessage(g.id, 'stock count at 5pm');
    for (const m of [await atBob, await atCarol]) {
      assert.equal(m.text, 'stock count at 5pm');
      assert.equal(m.from, g.jid);
      assert.equal(m.participant, 'alice@s.xb');
      assert.equal(m.id, ack.id);
    }
    await tick(100);
    assert.deepEqual(receipts.sort(), ['bob@s.xb:delivered', 'carol@s.xb:delivered']);

    await assert.rejects(dave.sendGroupMessage(g.id, 'let me in'), { code: 'not-member' });
    await assert.rejects(bob.addToGroup(g.id, ['dave']), { code: 'forbidden' });

    const updated = await alice.addToGroup(g.id, ['dave']);
    assert.equal(updated.participants.length, 4);
    const atDave = next(dave, 'message');
    await bob.sendGroupMessage(g.id, 'welcome dave');
    assert.equal((await atDave).participant, 'bob@s.xb');

    await carol.leaveGroup(g.id);
    assert.equal((await carol.listGroups()).length, 0);
    assert.equal((await alice.groupInfo(g.id)).participants.length, 3);

    for (const c of [alice, bob, carol, dave]) c.close();
  });
});

describe('presence', () => {
  test('watchers see online/offline and last seen', async () => {
    const alice = await connect('alice');
    alice.subscribePresence('bob');
    await next(alice, 'presence', (p) => p.from === 'bob@s.xb');

    // Connected is not online: only an open app (available) is.
    const bob = await connect('bob');
    assert.equal((await alice.lastSeen('bob')).online, false);
    const online = next(alice, 'presence', (p) => p.type === 'available');
    bob.setAvailable(true);
    await online;
    assert.equal((await alice.lastSeen('bob')).online, true);

    // Backgrounded (app closed but still connected): offline, last seen now.
    const away = next(alice, 'presence', (p) => p.type === 'unavailable');
    bob.setAvailable(false);
    assert.ok((await away).lastSeen > 0);
    bob.setAvailable(true);
    await next(alice, 'presence', (p) => p.type === 'available');

    const offline = next(alice, 'presence', (p) => p.type === 'unavailable');
    bob.close();
    const p = await offline;
    assert.ok(p.lastSeen > 0);
    alice.close();
  });
});

describe('media', () => {
  test('encrypted upload, download, forward without re-upload', async () => {
    const alice = await connect('alice');
    const bob = await connect('bob');
    const carol = await connect('carol');
    const photo = randomBytes(200_000);

    const got = next(bob, 'message');
    const sent = await alice.sendMedia('bob', photo, { mimetype: 'image/jpeg', caption: 'shelf 4' });
    const msg = await got;
    assert.equal(msg.media.mimetype, 'image/jpeg');
    assert.equal(msg.media.caption, 'shelf 4');
    assert.equal(Number(msg.media.size), photo.length);
    assert.ok((await bob.downloadMedia(msg.media)).equals(photo));

    // The server only holds ciphertext.
    const stored = await fs.readFile(path.join(dir, 'media', msg.media.sha256));
    assert.ok(!stored.includes(photo.subarray(0, 64)));
    assert.equal(stored.length, photo.length + 28);

    // Forwarding reuses the same file: still exactly one file on disk.
    const fwd = next(carol, 'message');
    await bob.forwardMedia('carol', msg.media);
    assert.ok((await carol.downloadMedia((await fwd).media)).equals(photo));
    assert.equal((await fs.readdir(path.join(dir, 'media'))).length, 1);

    // A tampered key fails authentication instead of returning garbage.
    const bad = { ...sent.media, key: randomBytes(32).toString('base64') };
    await assert.rejects(bob.downloadMedia(bad));

    for (const c of [alice, bob, carol]) c.close();
  });

  test('resumable upload: continues after a dropped connection', async () => {
    const { token } = media.issueToken('alice');
    const auth = { authorization: `Bearer ${token}` };
    const blob = randomBytes(300_000);
    const sha = createHash('sha256').update(blob).digest('hex');
    const status = async () => (await (await fetch(`${media.publicUrl}/upload/${sha}`, { headers: auth })).json());
    const put = (offset, body) =>
      fetch(`${media.publicUrl}/upload?sha256=${sha}&total=${blob.length}&offset=${offset}`, { method: 'POST', headers: auth, body });

    assert.deepEqual(await status(), { offset: 0 });
    // First 100 kB arrive, then the "connection drops" (the request ends early).
    assert.deepEqual(await (await put(0, blob.subarray(0, 100_000))).json(), { offset: 100_000 });
    assert.deepEqual(await status(), { offset: 100_000 });

    // Another user has no partial file here and can't add to alice's.
    const bobAuth = { authorization: `Bearer ${media.issueToken('bob').token}` };
    assert.deepEqual(await (await fetch(`${media.publicUrl}/upload/${sha}`, { headers: bobAuth })).json(), { offset: 0 });

    // Wrong offset: told where to continue.
    const wrong = await put(50_000, blob.subarray(50_000));
    assert.equal(wrong.status, 409);
    assert.equal((await wrong.json()).offset, 100_000);

    // The rest: the file is complete and checked.
    const done = await (await put(100_000, blob.subarray(100_000))).json();
    assert.equal(done.sha256, sha);
    assert.ok((await fs.readFile(path.join(dir, 'media', sha))).equals(blob));
    assert.equal((await status()).sha256, sha);
    assert.ok(!(await fs.readdir(path.join(dir, 'media'))).some((n) => n.endsWith('.part')));

    // Bytes that don't match the hash are thrown away.
    const other = randomBytes(1000);
    const badSha = createHash('sha256').update(randomBytes(8)).digest('hex');
    const bad = await fetch(`${media.publicUrl}/upload?sha256=${badSha}&total=${other.length}&offset=0`, { method: 'POST', headers: auth, body: other });
    assert.equal(bad.status, 400);
    assert.equal((await bad.json()).error, 'hash-mismatch');
  });

  test('upload needs a valid token; files expire', async () => {
    const res = await fetch(`${media.publicUrl}/upload`, {
      method: 'POST',
      headers: { authorization: 'Bearer alice.9999999999999.forged' },
      body: Buffer.from('x'),
    });
    assert.equal(res.status, 401);
    const expired = media.issueToken('alice', Date.now() - 3600_000).token;
    assert.equal(media.checkToken(expired), null);
    assert.ok((await media.sweep(Date.now() + 31 * 24 * 3600 * 1000)) >= 1);
  });
});
